function lecture(id, skillId, objectives, sections, workedExamples, misconceptions, checks) {
  return { id, skillId, objectives, sections, workedExamples, misconceptions, checks, assets: [] };
}

function question(id, skillId, difficulty, stem, options, answerIndex, reasons, reviews, cognitiveProcess, representationType, misconceptionTargets) {
  const stimulusMatch = /^HIS_R4_SQ(\d{3})_/u.exec(id);
  return {
    id,
    skillId,
    difficulty,
    stem,
    options,
    answerIndex,
    reasons,
    reviews,
    cognitiveProcess,
    representationType,
    misconceptionTargets,
    ...(stimulusMatch ? { stimulusId: `HIS_R4_ST${stimulusMatch[1]}` } : {}),
    assets: [],
  };
}

function stimulus(id, skillId, type, label, blocks, plainText, longDescription) {
  return {
    id,
    skillId,
    type,
    content: { label, blocks, sourceNote: "本材料為依課綱概念撰寫的原創史料型重構，不是歷史文獻原文。" },
    accessibility: { plainText, longDescription },
    assets: [],
  };
}

